from __future__ import annotations

from typing import Any, Callable, Type, TypeVar

from . import config, io_safe, utils
from .sessions import (
	SessionDirFull,
	SessionDirWhere,
	SessionFileFull,
	SessionFileKey,
	SessionFileWhere,
)

T = TypeVar("T")


class OperationType:
	"""
	Legal:
	- DDB.at("file")
	- DDB.at("file", key="subkey")
	- DDB.at("file", where=lambda k, v: ...)
	- DDB.at("dir", "*")
	- DDB.at("dir", "*", where=lambda k, v: ...)

	Illegal:
	- DDB.at("file", key="subkey", where=lambda k, v: ...)
	- DDB.at("dir", key="subkey", where=lambda k, v: ...)
	- DDB.at("dir", key="subkey")
	"""

	def __init__(self, path: str, key: str, where: Callable) -> None:
		self.dir = "*" in path
		self.file = not self.dir
		self.where = where is not None
		self.key = key is not None

		if self.key and self.where:
			raise TypeError("Cannot specify both key and where")
		if self.key and self.dir:
			raise TypeError("Cannot specify sub-key when selecting a folder. Specify the key in the path instead.")

	@property
	def file_normal(self) -> bool:
		return self.file and not self.where and not self.key

	@property
	def file_key(self) -> bool:
		return self.file and not self.where and self.key

	@property
	def file_where(self) -> bool:
		return self.file and self.where and not self.key

	@property
	def dir_normal(self) -> bool:
		return self.dir and not self.where and not self.key

	@property
	def dir_where(self) -> bool:
		return self.dir and self.where and not self.key


def at(*path, key: str = None, where: Callable[[Any, Any], bool] = None) -> DDBMethodChooser:
	"""
	Select a file or folder to perform an operation on.
	If you want to select a specific key in a file, use the `key` parameter,
	e.g. `DDB.at("file", key="subkey")`.

	If you want to select an entire folder, use the `*` wildcard,
	eg. `DDB.at("folder", "*")`, or `DDB.at("folder/*")`. You can also use
	the `where` callback to select a subset of the file or folder.

	If the callback returns `True`, the item will be selected. The callback
	needs to accept a key and value as arguments.

	Args:
	- `path`: The path to the file or folder. Can be a string, a
	comma-separated list of strings, or a list.
	- `key`: The key to select from the file.
	- `where`: A function that takes a key and value and returns `True` if the
	key should be selected.

	Beware: If you select a folder with the `*` wildcard, you can't use the `key` parameter.
	Also, you cannot use the `key` and `where` parameters at the same time.
	"""
	return DDBMethodChooser(path, key, where)


class DDBMethodChooser:
	__slots__ = ("path", "key", "where", "op_type")

	path: str
	key: str
	where: Callable[[Any, Any], bool]
	op_type: OperationType

	def __init__(
		self,
		path: tuple,
		key: str = None,
		where: Callable[[Any, Any], bool] = None,
	) -> None:
		# Convert path to a list of strings
		pc = []
		for p in path:
			pc += p if isinstance(p, list) else [p]
		self.path = "/".join([str(p) for p in pc])
		self.key = key
		self.where = where
		self.op_type = OperationType(self.path, self.key, self.where)
		# Invariants:
		# - Both key and where cannot be not None at the same time
		# - If key is not None, then there is no wildcard in the path.

	def exists(self) -> bool:
		"""
		Efficiently checks if a database exists. If the selected path contains
		a wildcard, it will return True if at least one file exists in the folder.


		If a key was specified, check if it exists in a database.
		The key can be anywhere in the database, even deeply nested.
		As long it exists as a key in any dict, it will be found.
		"""
		if self.where is not None:
			raise RuntimeError("DDB.at(where=...).exists() cannot be used with the where parameter")

		if not utils.file_exists(self.path):
			return False
		if self.key is None:
			return True
		# Key is passed and occurs is True
		return io_safe.partial_read(self.path, key=self.key) is not None

	def create(self, data: dict | None = None, force_overwrite: bool = False) -> None:
		"""
		Create a new file with the given data as the content. If the file
		already exists, a FileExistsError will be raised unless
		`force_overwrite` is set to True.

		Args:
		- `data`: The data to write to the file. If not specified, it will be `{}`
		will be written.
		- `force_overwrite`: If `True`, will overwrite the file if it already
		exists, defaults to False (optional).
		"""
		if self.where is not None or self.key is not None:
			raise RuntimeError("DDB.at().create() cannot be used with the where or key parameters")

		# Except if db exists and force_overwrite is False
		if not force_overwrite and self.exists():
			raise FileExistsError(
				f"Database {self.path} already exists in {config.storage_directory}. Pass force_overwrite=True to overwrite."
			)
		# Write db to file
		if data is None:
			data = {}
		io_safe.write(self.path, data)

	def delete(self) -> None:
		"""
		Delete the file at the selected path.
		"""
		if self.where is not None or self.key is not None:
			raise RuntimeError("DDB.at().delete() cannot be used with the where or key parameters")
		io_safe.delete(self.path)

	def read(self, as_type: Type[T] = None) -> dict | T | None:
		"""
		Reads a file or folder depending on previous `.at(...)` selection.

		Args:
		- `as_type`: If provided, return the value as the given type.
		Eg. as_type=str will return str(value).
		"""

		def type_cast(value):
			if as_type is None:
				return value
			return as_type(value)

		data = {}

		if self.op_type.file_normal:
			data = io_safe.read(self.path)

		elif self.op_type.file_key:
			data = io_safe.partial_read(self.path, self.key)

		elif self.op_type.file_where:
			file_content = io_safe.read(self.path)
			if file_content is None:
				return None
			for k, v in file_content.items():
				if self.where(k, type_cast(v)):
					data[k] = v

		elif self.op_type.dir_normal:
			pattern_paths = utils.find_all(self.path)
			data = {n.split("/")[-1]: io_safe.read(n) for n in pattern_paths}

		elif self.op_type.dir_where:
			for db_name in utils.find_all(self.path):
				k, v = db_name.split("/")[-1], io_safe.read(db_name)
				if self.where(k, type_cast(v)):
					data[k] = v

		return type_cast(data)

	def session(
		self, as_type: Type[T] = None
	) -> SessionFileFull[T] | SessionFileKey[T] | SessionFileWhere[T] | SessionDirFull[T] | SessionDirWhere[T]:
		"""
		Opens a session to the selected file(s) or folder, depending on previous
		`.at(...)` selection. Inside the with block, you have exclusive access
		to the file(s) or folder.
		Call `session.write()` to write the data to the file(s) or folder.

		Args:
		- `as_type`: If provided, cast the value to the given type.
		Eg. as_type=str will return str(value).

		Raises:
		- `FileNotFoundError`: If the file does not exist.
		- `KeyError`: If a key is specified and it does not exist.

		Returns:
		- Tuple of (session_object, data)
		"""
		if self.op_type.file_normal:
			return SessionFileFull(self.path, as_type)
		if self.op_type.file_key:
			return SessionFileKey(self.path, self.key, as_type)
		if self.op_type.file_where:
			return SessionFileWhere(self.path, self.where, as_type)
		if self.op_type.dir_normal:
			return SessionDirFull(self.path, as_type)
		if self.op_type.dir_where:
			return SessionDirWhere(self.path, self.where, as_type)

from __future__ import annotations

from contextlib import contextmanager
from typing import Any, Callable, Generic, Tuple, TypeVar

from . import io_unsafe, locking, utils

T = TypeVar("T")
JSONSerializable = TypeVar("JSONSerializable", str, int, float, bool, None, list, dict)


def type_cast(obj, as_type):
	return obj if as_type is None else as_type(obj)


class SessionBase:
	in_session: bool
	db_name: str
	as_type: T

	def __init__(self, db_name: str, as_type):
		self.in_session = False
		self.db_name = db_name
		self.as_type = as_type

	def __enter__(self):
		self.in_session = True
		self.data_handle = {}

	def __exit__(self, type, value, tb):
		write_lock = getattr(self, "write_lock", None)
		if write_lock is not None:
			if isinstance(write_lock, list):
				for lock in write_lock:
					lock._unlock()
			else:
				write_lock._unlock()
		self.write_lock, self.in_session = None, False

	def write(self):
		if not self.in_session:
			raise PermissionError("Only call write() inside a with statement.")


@contextmanager
def safe_context(super, self, *, db_names_to_lock=None):
	"""
	If an exception happens in the context, the __exit__ method of the passed super
	class will be called.
	"""
	super.__enter__()
	try:
		if isinstance(db_names_to_lock, str):
			self.write_lock = locking.WriteLock(self.db_name)
			self.write_lock._lock()
		elif isinstance(db_names_to_lock, list):
			self.write_lock = [locking.WriteLock(x) for x in self.db_name]
			for lock in self.write_lock:
				lock._lock()
		yield
	except BaseException as e:
		super.__exit__(type(e), e, e.__traceback__)
		raise e


########################################################################################
#### File sessions
########################################################################################


class SessionFileFull(SessionBase, Generic[T]):
	"""
	Context manager for read-write access to a full file.

	Efficiency:
	Reads and writes the entire file.
	"""

	def __enter__(self) -> Tuple[SessionFileFull, JSONSerializable | T]:
		with safe_context(super(), self, db_names_to_lock=self.db_name):
			self.data_handle = io_unsafe.read(self.db_name)
			return self, type_cast(self.data_handle, self.as_type)

	def write(self):
		super().write()
		io_unsafe.write(self.db_name, self.data_handle)


class SessionFileKey(SessionBase, Generic[T]):
	"""
	Context manager for read-write access to a single key-value item in a file.

	Efficiency:
	Uses partial reading, which allows only reading the bytes of the key-value item.
	When writing, only the bytes of the key-value and the bytes of the file after
	the key-value are written.
	"""

	def __init__(self, db_name: str, key: str, as_type: T):
		super().__init__(db_name, as_type)
		self.key = key

	def __enter__(self) -> Tuple[SessionFileKey, JSONSerializable | T]:
		with safe_context(super(), self, db_names_to_lock=self.db_name):
			self.partial_handle = io_unsafe.get_partial_file_handle(self.db_name, self.key)
			self.data_handle = self.partial_handle.partial_dict.value
			return self, type_cast(self.data_handle, self.as_type)

	def write(self):
		super().write()
		io_unsafe.partial_write(self.partial_handle)


class SessionFileWhere(SessionBase, Generic[T]):
	"""
	Context manager for read-write access to selection of key-value items in a file.
	The where callable is called with the key and value of each item in the file.

	Efficiency:
	Reads and writes the entire file, so it is not more efficient than
	SessionFileFull.
	"""

	def __init__(self, db_name: str, where: Callable[[Any, Any], bool], as_type: T):
		super().__init__(db_name, as_type)
		self.where = where

	def __enter__(self) -> Tuple[SessionFileWhere, JSONSerializable | T]:
		with safe_context(super(), self, db_names_to_lock=self.db_name):
			self.original_data = io_unsafe.read(self.db_name)
			for k, v in self.original_data.items():
				if self.where(k, v):
					self.data_handle[k] = v
			return self, type_cast(self.data_handle, self.as_type)

	def write(self):
		super().write()
		self.original_data.update(self.data_handle)
		io_unsafe.write(self.db_name, self.original_data)


########################################################################################
#### File sessions
########################################################################################


class SessionDirFull(SessionBase, Generic[T]):
	"""
	Context manager for read-write access to all files in a directory.
	They are provided as a dict of {str(file_name): dict(file_content)}, where the
	file name does not contain the directory name nor the file extension.

	Efficiency:
	Fully reads and writes all files.
	"""

	def __init__(self, db_name: str, as_type: T):
		super().__init__(utils.find_all(db_name), as_type)

	def __enter__(self) -> Tuple[SessionDirFull, JSONSerializable | T]:
		with safe_context(super(), self, db_names_to_lock=self.db_name):
			self.data_handle = {n.split("/")[-1]: io_unsafe.read(n) for n in self.db_name}
			return self, type_cast(self.data_handle, self.as_type)

	def write(self):
		super().write()
		for name in self.db_name:
			io_unsafe.write(name, self.data_handle[name.split("/")[-1]])


class SessionDirWhere(SessionBase, Generic[T]):
	"""
	Context manager for read-write access to selection of files in a directory.
	The where callable is called with the file name and parsed content of each file.

	Efficiency:
	Fully reads all files, but only writes the selected files.
	"""

	def __init__(self, db_name: str, where: Callable[[Any, Any], bool], as_type: T):
		super().__init__(utils.find_all(db_name), as_type)
		self.where = where

	def __enter__(self) -> Tuple[SessionDirWhere, JSONSerializable | T]:
		with safe_context(super(), self):
			selected_db_names, write_lock = [], []
			for db_name in self.db_name:
				lock = locking.WriteLock(db_name)
				lock._lock()
				k, v = db_name.split("/")[-1], io_unsafe.read(db_name)
				if self.where(k, v):
					self.data_handle[k] = v
					write_lock.append(lock)
					selected_db_names.append(db_name)
				else:
					lock._unlock()
			self.write_lock = write_lock
			self.db_name = selected_db_names
			return self, type_cast(self.data_handle, self.as_type)

	def write(self):
		super().write()
		for name in self.db_name:
			io_unsafe.write(name, self.data_handle[name.split("/")[-1]])

import json

import pytest
from path_dict import pd

import dictdatabase as DDB


def test_subread(use_compression, use_orjson, indent):
	name = "test_subread"
	j = {
		"a": "Hello{}",
		"b": [0, 1],
		"c": {"d": "e"},
	}

	DDB.at(name).create(j, force_overwrite=True)

	assert DDB.at(name, key="a").read() == "Hello{}"
	assert DDB.at(name, where=lambda k, v: isinstance(v, list)).read() == {"b": [0, 1]}

	assert DDB.at(name, key="f").read() is None

	assert DDB.at(name, key="b").read() == [0, 1]
	assert DDB.at(name, key="c").read() == {"d": "e"}

	j2 = {"a": {"b": "c"}, "b": {"d": "e"}}
	DDB.at("test_subread2").create(j2, force_overwrite=True)
	assert DDB.at("test_subread2", key="b").read() == {"d": "e"}

	assert DDB.at("none", key="none").read() is None

	j3 = {"a": {"b": {"\\c\\": {"a": "a"}}}}
	DDB.at("test_subread3").create(j3, force_overwrite=True)
	assert DDB.at("test_subread3", key="a").read() == {"b": {"\\c\\": {"a": "a"}}}


def test_subwrite(use_compression, use_orjson, indent):
	name = "test_subwrite"
	j = {
		"b": {"0": 1},
		"c": {"d": "e"},
	}

	DDB.at(name).create(j, force_overwrite=True)
	with DDB.at(name, key="c").session(as_type=pd) as (session, task):
		task["f"] = lambda x: (x or 0) + 5
		session.write()
	assert DDB.at(name, key="c").read() == {"d": "e", "f": 5}

	with DDB.at(name, key="b").session(as_type=pd) as (session, task):
		task["f"] = lambda x: (x or 0) + 2
		session.write()

	assert DDB.at(name, key="f").read() is None

	with pytest.raises(KeyError):
		with DDB.at(name, key="none").session() as (session, key):
			session.write()


def test_write_file_where(use_compression, use_orjson, indent):
	name = "test_write_file_where"
	j = {
		"a": 1,
		"b": 20,
		"c": 3,
		"d": 40,
	}

	DDB.at(name).create(j, force_overwrite=True)

	with DDB.at(name, where=lambda k, v: v > 10).session() as (session, vals):
		vals.update({"b": 30, "d": 50, "e": 60})
		session.write()
	assert DDB.at(name).read() == {
		"a": 1,
		"b": 30,
		"c": 3,
		"d": 50,
		"e": 60,
	}


def test_dir_where(use_compression, use_orjson, indent):
	name = "test_dir_where"
	for i in range(5):
		DDB.at(name, i).create({"k": i}, force_overwrite=True)

	with DDB.at(name, "*", where=lambda k, v: v["k"] > 2).session() as (session, vals):
		for k, v in vals.items():
			v["k"] += 1
		session.write()
	assert DDB.at(name, "*").read() == {
		"0": {"k": 0},
		"1": {"k": 1},
		"2": {"k": 2},
		"3": {"k": 4},
		"4": {"k": 5},
	}

import json

import orjson
import pytest

import dictdatabase as DDB
from dictdatabase import config, io_bytes, io_unsafe, utils

data = {
	"a": 1,
	"b": {
		"c": 2,
		"cl": [1, "\\"],
		"d": {
			"e": 3,
			"el": [1, "\\"],
		},
	},
	"l": [1, "\\"],
}


def string_dump(db: dict):
	if not config.use_orjson:
		return json.dumps(db, indent=config.indent, sort_keys=True).encode()
	option = (orjson.OPT_INDENT_2 if config.indent else 0) | orjson.OPT_SORT_KEYS
	return orjson.dumps(db, option=option)


def test_indentation(use_compression, use_orjson, indent):
	DDB.at("test_indentation").create(data, force_overwrite=True)

	with DDB.at("test_indentation", key="b").session() as (session, db_b):
		db_b["c"] = 3
		session.write()
	data["b"]["c"] = 3

	assert io_bytes.read("test_indentation") == string_dump(data)

	# Accessing a key not at root level should raise an error
	with pytest.raises(KeyError):
		with DDB.at("test_indentation", key="d").session() as (session, db_d):
			session.write()
	assert io_bytes.read("test_indentation") == string_dump(data)

import pytest
from path_dict import PathDict

import dictdatabase as DDB


def test_where(use_compression, use_orjson, indent):
	for i in range(10):
		DDB.at("test_select", i).create({"a": i}, force_overwrite=True)

	s = DDB.at("test_select/*", where=lambda k, v: v["a"] > 7).read()

	assert s == {"8": {"a": 8}, "9": {"a": 9}}

	with pytest.raises(KeyError):
		DDB.at("test_select/*", where=lambda k, v: v["b"] > 5).read()

	assert DDB.at("nonexistent/*", where=lambda k, v: v["a"] > 5).read() == {}

	assert DDB.at("nonexistent", where=lambda k, v: v["a"] > 5).read() is None

	s = DDB.at("test_select/*", where=lambda k, v: v.at("a").get() > 7).read(as_type=PathDict)
	assert s.get() == {"8": {"a": 8}, "9": {"a": 9}}
